insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('620d88b2-ac3a-5b4f-9b74-e576f879960e', 'Forania 1. Paróquia Transfiguração do Senhor. Não tem página no site da arquidiocese; contatos da lista de igrejas jubilares (2025). Sem horário: nenhuma fonte oficial com a grade regular de missas. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesesalvador.org.br/orientacoes-como-receber-as-indulgencias-durante-o-jubileu-ordinario-do-ano-2025-jubileu-da-esperanca-na-arquidiocese-de-sao-salvador-da-bahia/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('9a8cdd47-02f1-5153-b367-ecfe5b11a5f3', 'Forania 1. Criada em 17 de novembro de 1954. Sem horário: a página da paróquia no site da arquidiocese não publica horários. E-mail publicado é pessoal do pároco e ficou fora.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-tororo/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('59a106d0-e7f1-57b7-97c7-a1d05b62d59b', 'Forania 1. Paróquia Nossa Senhora da Conceição da Praia. Sem página no site da arquidiocese; contatos da lista de igrejas jubilares (2025). Sem horário: nenhuma fonte oficial com a grade regular de missas.', '{"https://arquidiocesesalvador.org.br/orientacoes-como-receber-as-indulgencias-durante-o-jubileu-ordinario-do-ano-2025-jubileu-da-esperanca-na-arquidiocese-de-sao-salvador-da-bahia/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('29b9b28d-afe3-584c-a1f2-0fae36ae6068', 'Forania 1. Criada em 1944. Sem horário: a página da paróquia no site da arquidiocese não publica horários.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-da-saude-e-gloria/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('8a954bc8-b883-5df9-b524-34d36a634950', 'Forania 1. Criada em 1561. Sem horário: a página da paróquia no site da arquidiocese não publica horários e o site citado por ela não respondeu ou está desatualizado.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-da-vitoria/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('c4fccbb3-5223-5499-8819-fee073e2acb8', 'Forania 1. Criada em 30 de março de 1971. Sem horário: a página da paróquia no site da arquidiocese não publica horários.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-de-lourdes/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('9293b8dc-ed48-5b3f-99f0-f63cfaa4b790', 'Forania 1. Criada em 1894. Sem horário: a página da paróquia no site da arquidiocese não publica horários. Facebook citado pela arquidiocese em 2020: paroquia.denazare.3.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-de-nazare/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/","https://arquidiocesesalvador.org.br/pastoral-da-comunicacao-nas-paroquias-organiza-transmissoes-de-missas-via-redes-sociais/"}', ''),
  ('3d658750-a80b-5c0a-a387-7da0efb68f23', 'Forania 1. Criada em 16 de outubro de 1954. Sem horário: a página da paróquia no site da arquidiocese não publica horários. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-santa-teresinha-do-menino-jesus-e-da-santa-face/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('f0c58799-373f-56a7-8c19-d673de11b670', 'Forania 1. Criada em 20 de julho de 1723. Horários do site da paróquia; o jornal do site vai só até abril de 2021. Fora do formato: Apostolado da Oração: primeira sexta-feira do mês, 8h. Honra a São José: todo dia 19, 8h.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-santissimo-sacramento-e-santana/","https://www.salvesantana.org.br/missas--horaacuterios.html","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', 'media'),
  ('05d85a20-753f-5223-8e37-a0a1f2b24810', 'Forania 1. Criada em 1642. Sem horário: a página da paróquia no site da arquidiocese não publica horários. Fora do formato: Comunidades sem bairro na fonte: Nossa Senhora da Conceição do Boqueirão.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-santo-antonio-alem-do-carmo/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('08ef85c9-c510-5c9e-bed1-ddf1ecc7f209', 'Forania 1. Criada em 1679. Sem horário: a página da paróquia no site da arquidiocese não publica horários e o site citado por ela não respondeu ou está desatualizado. O site citado (paroquiadesaopedro.org) virou domínio estacionado.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-sao-pedro/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('665cc2ea-4d26-5b78-aa73-ee808c1cae8d', 'Forania 2A. Criada em 12 de agosto de 1975. Sem horário: a página da paróquia no site da arquidiocese não publica horários.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-deus-menino/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('87255bc5-9152-59c0-a913-685fb897ebac', 'Forania 2A. Criada em 07 de janeiro de 1983. Sem horário: a página da paróquia no site da arquidiocese não publica horários e o site citado por ela não respondeu ou está desatualizado. O blog da paróquia citado pela arquidiocese traz horários, mas a última postagem é de 2010. Fora do formato: Comunidades sem bairro na fonte: São José.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-jesus-de-nazare/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('8b42d704-b16d-529c-908b-ca6cff53cb0f', 'Forania 2A. Criada em 11 de abril de 1718. Sem horário: a página da paróquia no site da arquidiocese não publica horários.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-de-brotas/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('b97610a8-34b8-57f7-8933-1605f3f107ff', 'Forania 2A. Criada em 10 de março de 1980. Sem horário: a página da paróquia no site da arquidiocese não publica horários. Facebook citado pela arquidiocese em 2020: pfatimaacupe.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-nossa-senhora-de-fatima-acupe-de-brotas/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/","https://arquidiocesesalvador.org.br/pastoral-da-comunicacao-nas-paroquias-organiza-transmissoes-de-missas-via-redes-sociais/"}', ''),
  ('bf8050a4-3746-5c1f-b09f-a1d50b717b2d', 'Forania 2A. Criada em 19 de maio de 1972. Sem horário: a página da paróquia no site da arquidiocese não publica horários. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-santa-rita-de-cassia/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('47f3cc3c-02fd-5a6d-b263-52284059e989', 'Forania 2A. Paróquia recente (primeiro aniversário de criação noticiado em maio de 2025). Sem página no site da arquidiocese; endereço de notícia de outubro de 2026. Sem horário: nenhuma fonte oficial com a grade regular de missas. Ponto no mapa aproximado: centro da cidade.', '{"https://arquidiocesesalvador.org.br/humildade-alegria-e-amor-que-transforma-este-e-o-tema-que-inspira-festejos-de-santa-teresa-davila/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
  ('a2b6a1dc-47f3-5a20-9167-7de24350d345', 'Forania 2A. Criada em 12 de fevereiro de 1981. Sem horário: a página da paróquia no site da arquidiocese não publica horários.', '{"https://arquidiocesesalvador.org.br/paroquia/paroquia-santo-antonio-cosme-de-farias/","https://arquidiocesesalvador.org.br/voce-sabe-o-que-e-e-quais-sao-as-paroquias-que-formam-cada-forania/"}', ''),
